import { Component, createEffect, createMemo, createSignal, For, Show } from "solid-js";

import LensManager from "#core/ui/lenses/lens-manager.js";
import { Icon as IconUtils } from "#core/ui/utilities/utilities-image.js";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { CloseButton } from "#core/ui-next/components/close-button.jsx";
import { FiligreeTitle } from "#core/ui-next/components/filigree-title.jsx";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { Hotkeys } from "#core/ui-next/components/hotkeys.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { KBMNavHelp } from "#core/ui-next/components/nav-help.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { IsControllerActive, IsKeyboardActive, IsMouseActive, IsTouchActive } from "#core/ui-next/services/input.js";
import { ComponentUtilities } from "#core/ui-next/utilities/component-utilities.js";

import { ToggleGeneralAppealNumbersEvent } from "#base/ui/lenses/layer/general-appeal-layer.js";
import { TicketSection } from "#base/ui-next/tooltips/plot-tooltip/components/utility.jsx";

import styles from "#base/ui/general-appeal-legend/panel-general-appeal-legend.scss?url";
//-------------------------------------------------------------
//#region Constants
// Ideally we move this data somewhere else
// So it's shared between the layer and lens.
//-------------------------------------------------------------
const APPEAL_DATA: { description: string; color: string }[] = [
	{
		description: "LOC_UI_GENERAL_APPEAL_LEGEND_BREATHTAKING",
		color: "rgb(8, 88, 13)",
	},
	{
		description: "LOC_UI_GENERAL_APPEAL_LEGEND_CHARMING",
		color: "rgb(149, 197, 35)",
	},
	{
		description: "LOC_UI_GENERAL_APPEAL_LEGEND_AVERAGE",
		color: "rgb(205, 189, 189)",
	},
	{
		description: "LOC_UI_GENERAL_APPEAL_LEGEND_NATURAL_WONDER",
		color: "rgb(100, 40, 250)",
	},
];
//-------------------------------------------------------------
//#region Main Panel
//-------------------------------------------------------------
const GeneralAppealPanel: Component = () => {
	const [showDetails, setShowDetails] = createSignal<boolean>(Configuration.getUser().getValue("ShowAppealValues"));
	const isKBM = createMemo(() => IsKeyboardActive() || IsMouseActive());
	const navHelp = () => {
		const icon = IconUtils.getIconFromActionName("unit-skip-turn");

		if (icon != "ICON_KEY_SPACE") {
			return (
				<KBMNavHelp
					actionName="unit-skip-turn"
					class="mx-2 size-12"
				/>
			);
		} else {
			return <div class="size-12 bg-contain bg-no-repeat img-pc_icon_space mx-2" />;
		}
	};

	createEffect(() => {
		if (IsControllerActive()) {
			Input.setActiveContext(InputContext.Dual);
		} else {
			Input.setActiveContext(InputContext.World);
		}
	});

	createEffect(() => {
		Configuration.getUser().setValue("ShowAppealValues", showDetails());
		window.dispatchEvent(new ToggleGeneralAppealNumbersEvent(showDetails()));
	});

	return (
		<div class="absolute h-screen">
			<Panel
				name="Syncretism Screen"
				id="screen-syncretism"
				class={"relative flex-col py-2 pointer-events-auto img-tooltip-bg fxs-subsystem-frame pt-4 mt-10"}
				autoFocus={false}
				onCancelInput={() => LensManager.setActiveLens("fxs-default-lens")}
			>
				<div class="inset-0 absolute frame-box" />
				<Hotkeys
					hotkeys={[
						{
							hotkeyAction: "shell-action-1",
							navTrayText: showDetails()
								? "LOC_UI_GENERAL_APPEAL_LEGEND_HIDE_NUMBERS"
								: "LOC_UI_GENERAL_APPEAL_LEGEND_SHOW_NUMBERS",
							onActivate: () => {
								setShowDetails(!showDetails());
								useAudio("AppealLens")(showDetails() ? "open" : "close");
							},
						},
						{
							// @ts-expect-error apparently this isn't registered as an option
							hotkeyAction: "touch-tap",
							onActivate: () => {
								setShowDetails(!showDetails());
								useAudio("AppealLens")(showDetails() ? "open" : "close");
							},
						},
						{
							// @ts-expect-error apparently this isn't registered as an option
							hotkeyAction: "unit-skip-turn",
							onActivate: () => {
								setShowDetails(!showDetails());
								useAudio("AppealLens")(showDetails() ? "open" : "close");
							},
						},
					]}
				/>
				<div class="relative flex flex-col px-6 w-96 items-stretch max-h-full">
					<FiligreeTitle.H3
						class="mb-1 flex items-center"
						textClass="text-base"
						text="LOC_UI_GENERAL_APPEAL_LEGEND_HEADER"
					/>
					<TicketSection class="flex-auto min-h-0 flex flex-col py-4">
						<For each={APPEAL_DATA}>
							{(item) => (
								<div class="flex flex-row items-center relative min-h-16 mb-2">
									<div
										class="absolute general-appeal-legend-hex size-16 bg-contain bg-no-repeat"
										// eslint-disable-next-line solid/style-prop
										style={{ "fxs-background-image-tint": item.color }}
									/>
									<L10n.Stylize
										class="font-body text-sm ml-16"
										text={item.description}
									/>
								</div>
							)}
						</For>
					</TicketSection>
					<AudioContextProvider segment="AppealLens">
						<Show
							fallback={<div class="size-2" />}
							when={!IsControllerActive()}
						>
							<div class="flex flex-row justify-center items-center">
								<Show when={IsTouchActive()}>
									<Icon
										class="size-8 m-3"
										name={`url("blp:handpointer")`}
										isUrl={true}
									/>
								</Show>
								<Show when={isKBM()}>{navHelp()}</Show>
								<L10n.Stylize
									text={
										showDetails()
											? "LOC_UI_GENERAL_APPEAL_LEGEND_HIDE_NUMBERS"
											: "LOC_UI_GENERAL_APPEAL_LEGEND_SHOW_NUMBERS"
									}
									class="text-sm font-body uppercase mr-2"
									style={{
										"letter-spacing": "-0.5px",
									}}
									role="heading"
								/>
							</div>
						</Show>
					</AudioContextProvider>
				</div>
				<CloseButton
					class={`${IsControllerActive() ? "hidden" : ""} absolute right-1 top-1`}
					onActivate={() => {
						LensManager.setActiveLens("fxs-default-lens");
					}}
					hotkeyAction="cancel"
					navTrayText="LOC_GENERIC_BACK"
				/>
			</Panel>
		</div>
	);
};
//#endregion

defineLegacyComponent("panel-general-appeal-legend", { classNames: ["absolute"] }, (_attrs, _element) => {
	return <GeneralAppealPanel />;
});
ComponentUtilities.loadStyles(styles);
